/* Company form: exact SIRET lookup, editable imports, social choices and fixed salary date. */
const retirementChoices=['À définir','AG2R LA MONDIALE','Malakoff Humanis','PRO BTP','KLESIA','APICIL','AGRICA','AUDIENS','B2V','IRP AUTO','LOURMEL','IRCEM','CGRR','IRCOM','BTPR','CRC','Autre'];
const insuranceChoices=['À définir','PRO BTP','AG2R LA MONDIALE','Malakoff Humanis','KLESIA','APICIL','AGRICA','AUDIENS','IRP AUTO','IRCEM','BTPR','Autre'];
const holidayChoices=['À définir','Non applicable','CIBTP Île-de-France','CIBTP Centre','CIBTP Grand Est','CIBTP Grand Ouest','CIBTP Méditerranée','CIBTP Nord-Ouest','CIBTP Rhône-Alpes Auvergne','CIBTP Sud-Ouest','Congés BTP Antilles-Guyane — Guadeloupe','Congés BTP Antilles-Guyane — Martinique','Congés BTP Antilles-Guyane — Guyane','Congés BTP La Réunion','CNETP — Travaux publics','Caisse des coopératives du BTP','Autre'];
const regionalCarsatChoices=['Carsat Alsace-Moselle','Carsat Aquitaine','Carsat Auvergne','Carsat Bourgogne-Franche-Comté','Carsat Bretagne','Carsat Centre-Val de Loire','Carsat Centre-Ouest','Carsat Hauts-de-France','Carsat Languedoc-Roussillon','Carsat Midi-Pyrénées','Carsat Nord-Est','Carsat Normandie','Carsat Pays de la Loire','Carsat Rhône-Alpes','Carsat Sud-Est'];
const overseasChoices=['CGSS Guadeloupe','CGSS Martinique','CGSS Guyane','CGSS La Réunion','CSS Mayotte'];
const collectionChoices=['À définir','Urssaf','Urssaf Île-de-France','Urssaf Alsace','Urssaf Aquitaine','Urssaf Auvergne','Urssaf Normandie','Urssaf Bourgogne','Urssaf Bretagne','Urssaf Centre-Val de Loire','Urssaf Champagne-Ardenne','Urssaf Corse','Urssaf Franche-Comté','Urssaf Languedoc-Roussillon','Urssaf Limousin','Urssaf Lorraine','Urssaf Midi-Pyrénées','Urssaf Nord-Pas-de-Calais','Urssaf Pays de la Loire','Urssaf Picardie','Urssaf Poitou-Charentes','Urssaf Provence-Alpes-Côte d’Azur','Urssaf Rhône-Alpes','CGSS',...overseasChoices,'MSA','Autre'];
const baseRetirementChoices=['À définir','CNAV — Assurance retraite Île-de-France',...regionalCarsatChoices,...overseasChoices,'MSA','Autre'];
const atmpBodyChoices=['À définir','Cramif — Île-de-France',...regionalCarsatChoices,...overseasChoices,'MSA','Autre'];
let registryProposal=null,registryApplied=null,registryRequest=0,registryAbort=null;
function choiceWithExisting(name,label,value,options){return selectField(name,label,value||'À définir',value&&!options.includes(value)?[...options,value]:options);}
function currentPayment(){try{return CompanyUtils.formatDate(CompanyUtils.paymentDate(period()));}catch{return'Choisir un mois';}}
function refreshCompanyOptions(){const current=company;$('#company').innerHTML=db.companies.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('#company').value=current;}
function companyOrganismCard(title,body,wide=false){return `<fieldset class="company-organism-card${wide?' company-organism-wide':''}"><legend>${esc(title)}</legend><div class="company-organism-fields">${body}</div></fieldset>`;}
function companyOrganismForm(c){return `<div class="wide company-organisms-grid">`+
companyOrganismCard('Organismes de recouvrement des cotisations',choiceWithExisting('collectionBody','Organisme de recouvrement',c.collectionBody,collectionChoices)+field('collectionOffice','Caisse locale / organisme exact',c.collectionOffice)+field('collectionReference','Numéro de compte / référence d’affiliation',c.collectionReference))+
companyOrganismCard('Retraite de base',choiceWithExisting('baseRetirementScheme','Choisir la caisse de retraite de base',c.baseRetirementScheme,baseRetirementChoices)+field('baseRetirementOffice','Caisse gestionnaire / organisme de rattachement',c.baseRetirementOffice)+field('baseRetirementReference','Référence de rattachement (si disponible)',c.baseRetirementReference))+
companyOrganismCard('Retraite complémentaire',choiceWithExisting('retirementBody','Groupe de protection sociale',c.retirementBody,retirementChoices)+field('retirementOffice','Institution de retraite complémentaire',c.retirementOffice)+field('retirementReference','Numéro d’adhésion / référence d’affiliation',c.retirementReference))+
companyOrganismCard('Prévoyance',choiceWithExisting('providentBody','Organisme de prévoyance',c.providentBody,insuranceChoices)+field('providentOffice','Institution / nom exact',c.providentOffice)+field('providentReference','Référence du contrat de prévoyance',c.providentReference))+
companyOrganismCard('Mutuelle / complémentaire santé',choiceWithExisting('mutualBody','Organisme de complémentaire santé',c.mutualBody,[...insuranceChoices.filter(x=>x!=='Autre'),'Harmonie Mutuelle','Autre'])+field('mutualOffice','Mutuelle / institution exacte',c.mutualOffice)+field('mutualReference','Référence du contrat santé',c.mutualReference))+
companyOrganismCard('Caisse des congés payés',choiceWithExisting('cibtp','Caisse de congés payés',c.cibtp,holidayChoices)+field('holidayOffice','Nom exact de la caisse',c.holidayOffice)+field('holidayReference','Numéro d’adhérent / référence d’adhésion',c.holidayReference))+
companyOrganismCard('Accidents du travail / maladies professionnelles (AT/MP)',choiceWithExisting('atmpBody','Choisir la caisse AT/MP',c.atmpBody,atmpBodyChoices)+field('atmpOffice','Caisse exacte / autre organisme AT/MP',c.atmpOffice)+field('atmpRiskCode','Code risque AT/MP notifié',c.atmpRiskCode,'text','maxlength="20"')+field('atmpRate','Taux AT/MP notifié (%)',c.atmpRate,'number','min="0" max="100" step=".0001"')+field('atmpValidFrom','Date d’effet du taux',c.atmpValidFrom,'date')+field('atmpValidUntil','Fin de validité (si connue)',c.atmpValidUntil,'date')+field('atmpReference','Référence de notification Carsat / Cramif / CGSS',c.atmpReference)+`<p class="muted">Code et taux à reprendre sur la notification applicable à cet établissement.</p>`,true)+
`</div>`+`<div class="wide">${field('organisms','Autres organismes / notes',c.organisms)}</div><p class="wide muted">La retraite de base est renseignée pour le rattachement uniquement, sans créer de seconde cotisation vieillesse. Listes proposées non exhaustives : choisissez « Autre » et précisez le nom dans le champ associé si nécessaire. Confirmez les caisses exactes et leurs références avec les documents d’affiliation et de paramétrage DSN. Les taux de cotisation ne sont pas déduits des choix d’organismes.</p>`;}

companyEdit=function(){registryRequest++;registryAbort?.abort();registryProposal=null;registryApplied=null;const c=db.companies.find(c=>c.id===company);extendedForm(`<h2>Fiche entreprise et caisses sociales</h2><p>Renseignez le SIRET pour rechercher les informations publiques de l’établissement.</p>`+
section('1. Rechercher avec le SIRET',field('siret','SIRET — 14 chiffres',c.siret,'text','inputmode="numeric" maxlength="18" autocomplete="off"')+`<div class="lookup-action"><button id="lookupSiret" type="button" class="btn" onclick="lookupCompanySiret()">Rechercher l’entreprise</button></div><p id="registryStatus" class="wide muted" role="status" aria-live="polite">La recherche transmet uniquement le SIRET à l’API publique Recherche d’entreprises.</p><div id="registryProposal" class="wide"></div>`)+
section('2. Identité de l’entreprise',field('name','Raison sociale / nom affiché',c.name,'text','required maxlength="250"')+field('siren','SIREN',c.siren)+field('address','Adresse de l’établissement',c.address,'text','maxlength="500"')+field('ape','Code APE de l’établissement',c.ape)+field('sector','Secteur d’activité',c.sector,'text','required maxlength="100"')+field('legalForm','Forme juridique — code du registre',c.legalForm)+field('creationDate','Date de création de l’établissement',c.creationDate,'date')+conventionPicker(c.idcc,'company')+`<p class="wide muted" id="registryIdccHint">${c.registryIdccCandidates?'Conventions signalées dans le registre : '+esc(c.registryIdccCandidates)+'. À vérifier selon le dossier.':'La convention collective et les affiliations sociales sont à vérifier dans le dossier.'}</p>`)+
section('3. Choisir les caisses et organismes',companyOrganismForm(c))+
section('4. Paiement des salaires',`<div class="wide company-payment-grid"><label>Date calculée pour la période ${esc(period())}<input type="date" readonly value="${esc(CompanyUtils.paymentDate(period()))}" aria-label="Date de paiement des salaires"></label><label>Règle de paiement<input type="text" readonly value="Le 5 du mois suivant" aria-label="Règle de paiement des salaires"></label><p class="wide muted">Règle fixe pour toutes les périodes. Aucun report automatique selon les week-ends ou jours fériés.</p></div>`+field('agreements','Accords / règles de paie à vérifier',c.agreements))+`<p class="muted">Les informations importées restent modifiables avant l’enregistrement. La recherche ne choisit pas les caisses à votre place.</p>`,f=>{
const val=Object.fromEntries(f);CompanyAtmp.validate(val);val.name=val.name.trim();val.sector=val.sector.trim();if(!val.name||!val.sector)throw Error('Raison sociale et secteur requis.');val.siret=val.siret.trim()?CompanyUtils.normalizeSiret(val.siret):'';if(val.siret)val.siren=val.siret.slice(0,9);
for(const[k,detail]of[['collectionBody','collectionOffice'],['retirementBody','retirementOffice'],['providentBody','providentOffice'],['mutualBody','mutualOffice'],['cibtp','holidayOffice'],['baseRetirementScheme','baseRetirementOffice'],['atmpBody','atmpOffice']])if(val[k]==='Autre'&&!val[detail].trim())throw Error('Précisez le nom de l’organisme choisi dans le champ associé.');
const before=structuredClone(c);remember('Fiche entreprise et affiliations modifiées');db.profileHistory.push({at:new Date().toISOString(),company:c.id,before});Object.assign(c,val,{paymentRule:'NEXT_MONTH_5'});
if(registryApplied&&registryApplied.siret===val.siret){c.registrySource=registryApplied.source;c.registrySourceUrl=registryApplied.sourceUrl;c.registryCheckedAt=registryApplied.checkedAt;c.registrySiret=registryApplied.siret;c.registryIdccCandidates=registryApplied.idccCandidates;c.registryState=registryApplied.registryState;}else if(c.registrySiret!==val.siret){c.registryCheckedAt=null;c.registrySource=null;c.registrySourceUrl=null;c.registrySiret=null;c.registryIdccCandidates=null;c.registryState=null;}
// Keep historical paymentDate for reversibility, but never use it for new payments.
db.people.filter(p=>p.company===company).forEach(p=>invalidate(p.id));if(!save())throw Error('Enregistrement impossible. Exportez une sauvegarde avant de poursuivre.');refreshCompanyOptions();
});$('#form').dataset.companyEditor='true';}
async function lookupCompanySiret(){const form=$('#form');const status=$('#registryStatus'),button=$('#lookupSiret');registryProposal=null;$('#registryProposal').innerHTML='';let s;try{s=CompanyUtils.normalizeSiret(form.elements.siret.value);form.elements.siret.value=s;}catch(e){status.textContent=e.message;return;}const request=++registryRequest;registryAbort?.abort();const controller=new AbortController();registryAbort=controller;button.disabled=true;button.textContent='Recherche en cours…';status.textContent='Recherche de l’établissement dans le registre public…';const timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('https://recherche-entreprises.api.gouv.fr/search?q='+encodeURIComponent(s)+'&per_page=1&minimal=true&include=siege,matching_etablissements,complements',{headers:{Accept:'application/json'},credentials:'omit',referrerPolicy:'no-referrer',signal:controller.signal});if(!response.ok)throw Error(response.status===429?'Le registre reçoit trop de demandes. Réessayez plus tard.':'Le registre est indisponible (HTTP '+response.status+').');const proposal=CompanyUtils.mapRegistry(await response.json(),s);if(request!==registryRequest||!$('#modal').open||!button.isConnected||!form.elements.siret)return;const current=form.elements.siret.value.replace(/\s/g,'');if(current!==s){status.textContent='Le SIRET a changé pendant la recherche. Relancez la recherche.';return;}registryProposal={...proposal,checkedAt:new Date().toISOString()};status.textContent='Établissement trouvé. Vérifiez les informations avant de les utiliser.';$('#registryProposal').innerHTML=`<div class="registry-preview"><h3>${esc(proposal.name||'Dénomination non disponible')}</h3><p><strong>SIRET ${esc(proposal.siret)}</strong><br>${esc(proposal.address||'Adresse non disponible')}<br>APE : ${esc(proposal.ape||'Non disponible')} · Forme juridique : ${esc(proposal.legalForm||'Non disponible')}<br>État administratif : ${esc(proposal.registryState||'Non disponible')}</p>${proposal.idccCandidates?`<p>Conventions signalées (à vérifier) : ${esc(proposal.idccCandidates)}</p>`:''}<button type="button" class="btn" onclick="applyCompanyRegistry()">Utiliser ces informations</button><p class="muted">Seuls le nom, le SIREN, l’adresse, l’APE, la forme juridique et la date de création disponibles seront repris. Les autres champs seront conservés.</p></div>`;}catch(e){if(request===registryRequest&&$('#modal').open){status.textContent=(e.name==='AbortError'?'La recherche a expiré ou a été interrompue.':e.message==='Failed to fetch'?'Le registre est inaccessible depuis ce navigateur.':e.message)+' Vous pouvez renseigner la fiche manuellement.';}}finally{clearTimeout(timer);if(request===registryRequest&&button.isConnected){button.disabled=false;button.textContent='Rechercher l’entreprise';}}}
function applyCompanyRegistry(){const p=registryProposal,form=$('#form');if(!p||!$('#modal').open)return;let s;try{s=CompanyUtils.normalizeSiret(form.elements.siret.value);}catch(e){$('#registryStatus').textContent=e.message;return;}if(s!==p.siret){$('#registryStatus').textContent='Le SIRET a changé : relancez la recherche avant d’appliquer les données.';return;}for(const name of ['name','siren','address','ape','legalForm','creationDate'])if(p[name])form.elements[name].value=p[name];registryApplied={...p};$('#registryStatus').textContent='Informations reprises dans la fiche. Vérifiez les champs puis cliquez sur Enregistrer.';$('#registryIdccHint').textContent=p.idccCandidates?'Conventions signalées : '+p.idccCandidates+'. À confirmer selon votre dossier.':'Convention collective à confirmer dans le dossier.';}
const beforeCompanyRender=render;
render=function(){if(view!=='Entreprise')return beforeCompanyRender();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.textContent===view));const c=db.companies.find(c=>c.id===company);const organism=(body,exact,reference)=>`<strong>${esc(body||'À définir')}</strong>${exact?'<br>'+esc(exact):''}${reference?'<br><small>Réf. '+esc(reference)+'</small>':''}`;$('#app').innerHTML=head('Votre entreprise, prête pour la paie.','Retrouvez l’identité, les caisses sociales et la date de paiement.',`<button class="btn" onclick="companyEdit()">Renseigner / modifier l’entreprise</button>`)+`<section class="panel"><div class="heading"><div><h2>${esc(c.name)}</h2><p>${esc(c.address||'Adresse à renseigner')}</p></div><span class="badge">Paiement : ${currentPayment()}</span></div><div class="facts"><p>SIRET<br><strong>${esc(c.siret||'À renseigner')}</strong></p><p>SIREN<br><strong>${esc(c.siren||'À renseigner')}</strong></p><p>Activité / code APE<br><strong>${esc(c.sector)} · ${esc(c.ape||'À définir')}</strong></p><p>Convention / IDCC<br><strong>${esc(Conventions.display(c.idcc)||'À vérifier')}</strong></p></div>${c.registryCheckedAt?`<p class="muted">Recherche publique effectuée le ${new Date(c.registryCheckedAt).toLocaleString('fr-FR')} pour le SIRET ${esc(c.registrySiret)}. Données modifiables et à vérifier.</p>`:''}</section><section class="panel" style="margin-top:20px"><h2>Caisses et organismes de l’établissement</h2><div class="company-organisms-grid">${[['Organismes de recouvrement des cotisations',c.collectionBody,c.collectionOffice,c.collectionReference],['Retraite de base',c.baseRetirementScheme,c.baseRetirementOffice,c.baseRetirementReference],['Retraite complémentaire',c.retirementBody,c.retirementOffice,c.retirementReference],['Prévoyance',c.providentBody,c.providentOffice,c.providentReference],['Mutuelle / complémentaire santé',c.mutualBody,c.mutualOffice,c.mutualReference],['Caisse des congés payés',c.cibtp,c.holidayOffice,c.holidayReference]].map(([title,body,exact,reference])=>`<section class="company-organism-card"><h3>${esc(title)}</h3><p>${organism(body,exact,reference)}</p></section>`).join('')}<section class="company-organism-card company-organism-wide"><h3>Accidents du travail / maladies professionnelles (AT/MP)</h3><p>${organism(c.atmpBody,c.atmpOffice,'')}</p><p>${esc(CompanyAtmp.description(c)||'Code risque et taux à renseigner')}</p>${c.atmpValidUntil?`<p>Valable jusqu’au ${esc(c.atmpValidUntil.split('-').reverse().join('/'))}</p>`:''}${c.atmpReference?`<p>Notification : ${esc(c.atmpReference)}</p>`:''}</section></div>${c.organisms?`<p>Autres organismes / notes : ${esc(c.organisms)}</p>`:''}</section><section class="panel" style="margin-top:20px"><h2>Paiement des salaires : le 5 du mois suivant</h2><p>Période ${esc(period())} → <strong>${currentPayment()}</strong></p><p class="muted">Date fixe calculée automatiquement. Les bulletins de test déjà créés conservent leur photographie historique. Aucun virement n’est déclenché.</p></section>`;};
$('#period').onchange=()=>render();
document.querySelector('aside footer').innerHTML='RH & paie multi-activités<br>Version de travail · 0.9.11<br>Maguy · espace privé';render();
